@extends('layouts.app') @section('content')<h2>Kalender Jadwal Mingguan</h2><p class="text-muted">Tampilan visual jadwal sekolah untuk minggu berjalan.</p><div class="card p-3"><div id="calendar"></div></div>@endsection @push('scripts')<link href="https://cdn.jsdelivr.net/npm/fullcalendar@6.1.15/index.global.min.css" rel="stylesheet"><script src="https://cdn.jsdelivr.net/npm/fullcalendar@6.1.15/index.global.min.js"></script><script>document.addEventListener('DOMContentLoaded',function(){let c=document.getElementById('calendar');let cal=new FullCalendar.Calendar(c,{initialView:'timeGridWeek',locale:'id',firstDay:1,allDaySlot:false,slotMinTime:'07:00:00',slotMaxTime:'15:00:00',height:'auto',events:'{{ route('schedules.events') }}',eventDidMount:function(info){info.el.title='Guru: '+info.event.extendedProps.guru+' | Ruang: '+info.event.extendedProps.ruang;}});cal.render();});</script>@endpush